use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{collections::{BTreeMap,BTreeSet},fs,path::{Path,PathBuf}};
const R:&str="/home/ubuntu/src/zopro-perf-work/query-help175";
const Z:&str="/home/ubuntu/src/zk-tools/zopro";
const OLD:&str="/home/ubuntu/src/zopro-perf-work/service-trace175";
const REPORT:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-29-query-help175";
type Event=[u64;10];
fn r(p:&str)->PathBuf{Path::new(R).join(p)}
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn pin(p:&mut BTreeMap<String,String>,f:impl AsRef<Path>){let f=f.as_ref();p.insert(f.display().to_string(),hash(f));}
fn encode(events:&[Event])->Vec<u8>{events.iter().flat_map(|e|e.iter().flat_map(|v|v.to_le_bytes())).collect()}
fn decode(bytes:&[u8])->Result<Vec<Event>,String>{
 if bytes.len()%80!=0{return Err("truncated event payload".into())}
 let events:Vec<Event>=bytes.chunks_exact(80).map(|b|core::array::from_fn(|j|u64::from_le_bytes(b[j*8..j*8+8].try_into().unwrap()))).collect();
 let mut map=BTreeMap::new();for e in &events{if e[0]==0||e[0]>>32!=e[7]||e[7]>32||e[0]&0xffffffff==0||e[6]<e[5]||e[6]==0||e[9]<e[8]||map.insert(e[0],*e).is_some(){return Err("invalid event identity/clock".into())}}
 for e in &events{let mut seen=BTreeSet::new();let mut id=e[0];while id!=0{if !seen.insert(id){return Err("ancestry cycle".into())}let node=map.get(&id).ok_or("missing parent")?;if node[1]!=0{let p=map.get(&node[1]).ok_or("missing parent")?;if p[5]>node[5]||p[6]<node[6]{return Err("parent containment".into())}}id=node[1];}}
 for worker in 0..33{let mut leaves:Vec<_>=events.iter().filter(|e|e[7]==worker&&e[8]!=0).collect();leaves.sort_by_key(|e|e[5]);for pair in leaves.windows(2){if pair[0][6]>pair[1][5]{return Err("serial overlap".into())}}}
 for e in events.iter().filter(|e|e[8]!=0){let mut parent=e[1];while parent!=0{let p=map[&parent];if p[8]!=0{return Err("nested serial service".into())}parent=p[1];}}
 Ok(events)
}
fn query(id:u64,map:&BTreeMap<u64,Event>)->Option<&'static str>{let mut next=id;while next!=0{let e=map[&next];match e[2]{6=>return Some("a"),2=>return Some("kh"),5=>return Some("g2"),_=>{}}next=e[1];}None}
fn overlap(a:u64,b:u64,c:u64,d:u64)->u64{b.min(d).saturating_sub(a.max(c))}
fn coverage(events:&[Event],owner:u64,name:&str,start:u64,end:u64)->Value{
 assert!(end>=start);let map:BTreeMap<_,_>=events.iter().map(|e|(e[0],*e)).collect();let mut groups=BTreeMap::<String,(u64,u64,usize,usize)>::new();let mut records=vec![];let mut covered=0;
 for e in events.iter().filter(|e|e[7]==owner&&e[8]!=0){let elapsed=overlap(start,end,e[5],e[6]);if elapsed==0{continue}let logical=query(e[0],&map).unwrap_or("unclassified");let full=e[5]>=start&&e[6]<=end;let cpu=if full{e[9]-e[8]}else{0};let g=groups.entry(logical.to_owned()).or_default();g.0+=elapsed;g.1+=cpu;g.2+=usize::from(full);g.3+=usize::from(!full);covered+=elapsed;records.push(json!({"id":e[0],"kind":e[2],"query":logical,"overlap_ns":elapsed,"full_leaf":full,"CPU_ns":if full{json!(cpu)}else{Value::Null},"start_ns":e[5],"end_ns":e[6]}));}
 assert!(covered<=end-start);let foreign:u64=groups.iter().filter(|(k,_)|k.as_str()!=name&&k.as_str()!="unclassified").map(|(_,v)|v.0).sum();
 let detail:BTreeMap<_,_>=groups.into_iter().map(|(k,(wall,cpu,full,partial))|(k,json!({"service_span_overlap_ns":wall,"fully_contained_CPU_ns":cpu,"fully_contained_leaves":full,"partially_clipped_leaves":partial}))).collect();
 json!({"owner_worker":owner,"start_ns":start,"end_ns":end,"interval_ns":end-start,"serial_service_span_overlap_ns":covered,"foreign_service_span_overlap_ns":foreign,"foreign_span_fraction":if end==start{0.}else{foreign as f64/(end-start)as f64},"uncovered_elapsed_ns":end-start-covered,"by_logical_query":detail,"records":records})
}
fn last_label(events:&[Event],serial:bool,window:bool)->String{let map:BTreeMap<_,_>=events.iter().map(|e|(e[0],*e)).collect();let selected=events.iter().filter(|e|if serial{e[8]!=0}else if window{[10,11,12].contains(&e[2])}else{[2,5,6].contains(&e[2])}).max_by_key(|e|e[6]).unwrap();query(selected[0],&map).unwrap().to_owned()}
fn median(mut values:Vec<f64>)->f64{values.sort_by(f64::total_cmp);assert_eq!(values.len(),9);values[4]}
fn main(){
 let graphs_path=Path::new(Z).join("docs/benchmarks/2026-10-29-service-trace175/artifacts/graphs.json");let graphs=read(&graphs_path);let manifest=Path::new(Z).join("docs/benchmarks/2026-10-29-balanced-kh-adoption/artifacts/production-source-manifest.json");let m=read(&manifest);let mut pins=BTreeMap::new();pin(&mut pins,&graphs_path);pin(&mut pins,&manifest);for(f,h)in m["source_files_sha256"].as_object().unwrap(){let p=Path::new(Z).join(f);assert_eq!(hash(&p),h.as_str().unwrap());pin(&mut pins,p);}for f in["service_trace.rs","patch.rs","flow-body.rs","analysis.json"]{pin(&mut pins,Path::new(OLD).join(f));}for f in["design.md","analyze.rs","analyze","analyze-tests","tests.log"]{pin(&mut pins,r(f));}
 let mut rows=vec![];let mut raw=vec![];let mut labels:BTreeMap<String,BTreeMap<String,usize>>=BTreeMap::new();
 for g in graphs.as_array().unwrap().iter().filter(|g|g["job"]["mode"]=="on"&&g["job"]["phase"]=="main"){
  let summary=&g["graph"];assert_eq!(summary["complete"],true);assert_eq!(summary["dropped"],0);let file=summary["file"].as_str().unwrap();assert_eq!(hash(file),summary["sha256"].as_str().unwrap());pin(&mut pins,file);let bytes=fs::read(file).unwrap();let events=decode(&bytes).unwrap();assert_eq!(events.len()as u64,summary["events"].as_u64().unwrap());assert_eq!(encode(&events),bytes);
  let log=Path::new(OLD).join("runs").join(g["job"]["name"].as_str().unwrap()).join("stdout.log");pin(&mut pins,&log);let text=fs::read_to_string(log).unwrap();let metadata=text.lines().filter_map(|l|l.strip_prefix("GRAPH ")).map(|s|serde_json::from_str::<Value>(s).unwrap()).find(|v|v["file"]==file).unwrap();assert_eq!(metadata["record_bytes"],80);assert_eq!(metadata["limit_per_thread"],1024);assert_eq!(metadata["thread_lengths"].as_array().unwrap().len(),33);assert!(metadata["thread_dropped"].as_array().unwrap().iter().all(|v|v==0));let mut at=0;for(i,n)in metadata["thread_lengths"].as_array().unwrap().iter().enumerate(){let worker=if i==32{0}else{i+1}as u64;let n=n.as_u64().unwrap()as usize;assert!(n<=1024);for slot in 0..n{let e=events[at];assert_eq!(e[7],worker);assert_eq!(e[0]&0xffffffff,(slot+1)as u64);at+=1;}}assert_eq!(at,events.len());
  let map:BTreeMap<_,_>=events.iter().map(|e|(e[0],*e)).collect();let mut qs=BTreeMap::new();for(name,kind,wkind)in[("a",6,10),("kh",2,11),("g2",5,12)]{let root:Vec<_>=events.iter().filter(|e|e[2]==kind).collect();assert_eq!(root.len(),1);let q=*root[0];assert_eq!(q[0],summary["queries"][name]["id"].as_u64().unwrap());let windows:Vec<_>=events.iter().filter(|e|e[2]==wkind&&query(e[0],&map)==Some(name)).collect();assert_eq!(windows.len(),summary["queries"][name]["windows"].as_array().unwrap().len());let last=windows.iter().map(|e|e[6]).max().unwrap();assert_eq!(last,summary["queries"][name]["windows"].as_array().unwrap().iter().map(|e|e["end_ns"].as_u64().unwrap()).max().unwrap());let cpu:u64=events.iter().filter(|e|e[8]!=0&&query(e[0],&map)==Some(name)).map(|e|e[9]-e[8]).sum();let prior=summary["queries"][name]["covered_serial_CPU_ms"].as_f64().unwrap();assert!((cpu as f64/1e6-prior).abs()<1e-9);let available=summary["queries"][name]["input_available_ns"].as_u64().unwrap();qs.insert(name,json!({"root_id":q[0],"owner_worker":q[7],"query_start_ns":q[5],"query_end_ns":q[6],"last_window_end_ns":last,"last_window_to_return":coverage(&events,q[7],name,last,q[6]),"query_entry_to_input":coverage(&events,q[7],name,q[5],available),"covered_serial_CPU_ns":cpu}));}
  let last_root=last_label(&events,false,false);let last_window=last_label(&events,false,true);let last_serial=last_label(&events,true,false);assert_eq!(last_root,summary["last_query"]);for(k,label)in[("query_return",&last_root),("window_callback",&last_window),("covered_serial",&last_serial)]{*labels.entry(k.into()).or_default().entry(label.clone()).or_default()+=1;}
  raw.push(json!({"file":file,"sha256":summary["sha256"],"events_in_original_order":events,"metadata":metadata}));rows.push(json!({"job":g["job"]["name"],"block":g["job"]["block"],"round":summary["round"],"last_query_return":last_root,"last_window_callback":last_window,"last_covered_serial":last_serial,"queries":qs}));
 }assert_eq!(rows.len(),9);
 let mut summaries=BTreeMap::new();for name in["a","kh","g2"]{let mut intervals=BTreeMap::new();for key in["last_window_to_return","query_entry_to_input"]{let select=|metric:&str|rows.iter().map(|g|g["queries"][name][key][metric].as_f64().unwrap()).collect::<Vec<_>>();let ns=select("interval_ns");let foreign=select("foreign_service_span_overlap_ns");let fractions=select("foreign_span_fraction");intervals.insert(key,json!({"median_interval_ms":median(ns)/1e6,"median_foreign_service_span_overlap_ms":median(foreign)/1e6,"median_foreign_span_fraction":median(fractions)}));}summaries.insert(name,json!(intervals));}
 for(p,h)in &pins{assert_eq!(hash(p),*h);}save(r("pins.json"),&json!(pins));save(r("decoded-events.json"),&json!(raw));let result=json!({"status":"complete offline analysis","graphs":9,"labels":labels,"queries":summaries,"per_graph":rows,"pins_verified":pins.len(),"raw_records_byte_exact":true,"all_prior_boundary_CPU_totals_match":true,"new_decoder_tests":3,"SDK_requests":0,"new_proof_exports":0,"independent_proof_ledger":17811,"production_changed":false,"adopted":false,"goal_active_original8_unmet":true,"inherited_M5":m["m5"],"limitations":"Service-span elapsed overlap includes descheduling inside leaves. CPU clocks are exact only for fully contained leaves; clipped CPU is unknown. Uncovered preparation/normalization/Horner/coordinator work remains. Boundary labels are not a causal critical path or recoverable proof time."});save(r("analysis.json"),&result);println!("Labels {}",result["labels"]);for(name,v)in summaries{println!("{name}: {v}");}let _=REPORT;
}
#[cfg(test)]mod tests{
use super::*;fn id(w:u64,s:u64)->u64{(w<<32)|s}
fn fixture()->Vec<Event>{vec![[id(0,1),0,0,0,0,0,110,0,0,0],[id(1,1),id(0,1),2,0,0,10,100,1,0,0],[id(2,1),id(0,1),6,0,0,5,70,2,0,0],[id(3,1),id(0,1),5,0,0,20,90,3,0,0],[id(4,1),id(1,1),11,0,0,12,40,4,0,0],[id(1,2),id(3,1),22,0,0,30,50,1,100,115],[id(1,3),id(3,1),22,0,0,60,80,1,120,140]]}
#[test]fn roundtrip_and_malformed_records(){let e=fixture();assert_eq!(decode(&encode(&e)).unwrap(),e);let mut bytes=encode(&e);bytes.pop();assert!(decode(&bytes).is_err());let mut bad=e.clone();bad[6][1]=123;assert!(decode(&encode(&bad)).is_err());let mut bad=e.clone();bad.push(e[1]);assert!(decode(&encode(&bad)).is_err());let mut bad=e.clone();bad[6][5]=45;assert!(decode(&encode(&bad)).is_err());}
#[test]fn clipped_wall_and_full_only_cpu(){let e=fixture();let v=coverage(&e,1,"kh",40,90);assert_eq!(v["foreign_service_span_overlap_ns"],30);assert_eq!(v["uncovered_elapsed_ns"],20);assert_eq!(v["by_logical_query"]["g2"]["fully_contained_CPU_ns"],20);assert_eq!(v["by_logical_query"]["g2"]["partially_clipped_leaves"],1);assert_eq!(v["records"][0]["CPU_ns"],Value::Null);assert_eq!(overlap(0,5,5,9),0);assert_eq!(coverage(&e,2,"a",40,90)["foreign_service_span_overlap_ns"],0);}
#[test]fn last_return_is_not_last_service(){let e=fixture();assert_eq!(last_label(&e,false,false),"kh");assert_eq!(last_label(&e,true,false),"g2");assert_eq!(last_label(&e,false,true),"kh");}
}
